import { haversineDistance } from "./geolocation";

/**
 * Approximate service area per City Corporation, as a centre + radius.
 *
 * These are DELIBERATELY approximations, not legal ward boundaries — we have no
 * polygon source, and inventing one that looks authoritative would be worse
 * than a circle that's honestly labelled as approximate. It exists to stop a
 * report being filed against an authority that plainly doesn't cover the spot
 * (a Chattogram pin sent to Dhaka North), not to adjudicate edge cases.
 *
 * Matched on name, since City Corporation ids are generated by the database.
 */
const REGIONS = [
  {
    match: /north/i,
    /* Gulshan-ish centre, reaching Uttara in the north and Tejgaon in the south. */
    lat: 23.8225,
    lng: 90.3915,
    radius: 13000,
  },
  {
    match: /south/i,
    /* Old Dhaka centre, reaching Dhanmondi and Sadarghat. */
    lat: 23.7215,
    lng: 90.4125,
    radius: 11000,
  },
];

/** The region for a City Corporation, or null when we have no boundary for it. */
export function regionForCityCorp(cityCorp) {
  if (!cityCorp?.name) return null;
  const found = REGIONS.find((region) => region.match.test(cityCorp.name));
  if (!found) return null;

  return {
    id: cityCorp.id,
    name: cityCorp.name,
    lat: found.lat,
    lng: found.lng,
    radius: found.radius,
  };
}

/**
 * Is this point inside the region? Unknown regions return true — an authority
 * we have no boundary for should not block reporting entirely.
 */
export function isInsideRegion(point, region) {
  if (!region) return true;
  if (point?.lat == null || point?.lng == null) return false;
  return (
    haversineDistance(
      { lat: Number(point.lat), lng: Number(point.lng) },
      region,
    ) <= region.radius
  );
}
